import jax
import jax.numpy as jnp
import numpy as np

# Test gammainc and gammaincc with a=inf and various finite x values
test_x_values = [0.5, 1.0, 2.0, 10.0]

for x_val in test_x_values:
    try:
        gammainc_result = float(jax.scipy.special.gammainc(jnp.inf, x_val))
        probe(f'gammainc_a_inf_x_{x_val}', gammainc_result)
    except Exception as e:
        probe(f'gammainc_a_inf_x_{x_val}_error', float('nan'))

    try:
        gammaincc_result = float(jax.scipy.special.gammaincc(jnp.inf, x_val))
        probe(f'gammaincc_a_inf_x_{x_val}', gammaincc_result)
    except Exception as e:
        probe(f'gammaincc_a_inf_x_{x_val}_error', float('nan'))

